resource 'INTL' (0) {
    NumberFormat {
        ".", ",", ";", /* decimal, thousands, list separators */
        "$\0x00\0x00", /* three currency symbol bytes */
        192, 0, 128, 47, 255, 96, /* currency/date flags, date separator, time cycle/format */
        " AM\0x00", " PM\0x00", /* AM and PM strings */
        ":\0x00\0x00\0x00\0x00\0x00\0x00\0x00\0x00", /* time separator and eight suffix bytes */
        0, 0 /* metric-system flag and version */
    }
};

resource 'INTL' (1) {
    DateFormat {
        {
            "Sunday";
            "Monday";
            "Tuesday";
            "Wednesday";
            "Thursday";
            "Friday";
            "Saturday";
        },
        {
            "January";
            "February";
            "March";
            "April";
            "May";
            "June";
            "July";
            "August";
            "September";
            "October";
            "November";
            "December";
        },
        0, 201, 0, 3, /* suppress day, format, leading zero, abbreviation length */
